/** Dữ liệu token cho styleguide. Tên/giá trị là DATA (render qua interpolation),
 *  không phải UI copy — nên không cần i18n. Giá trị hiển thị đọc live từ CSS var
 *  qua readCssVar() nên luôn khớp token thật (đổi token → styleguide tự đổi). */

export interface TokenRef {
  /** tên CSS custom property, VD '--bg-surface' */
  var: string;
  /** nhãn ngắn hiển thị */
  label: string;
}

export interface TokenGroup {
  label: string;
  items: TokenRef[];
  /** mô tả ngắn nhóm (tuỳ chọn) */
  note?: string;
  /** nếu set: page tính contrast từng item so với var này → badge AA/AAA/FAIL */
  contrastVs?: string;
}

const ref = (v: string, label = v.replace(/^--/, '')): TokenRef => ({ var: v, label });

/** Đọc giá trị đã resolve của 1 CSS var trên <html>. */
export function readCssVar(name: string): string {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

/* =============================== COLORS ===============================
 * Tổ chức 2 TẦNG (chuẩn design-system: Radix / Atlassian / Material 3 / IBM
 * Carbon):
 *   TẦNG 1 — PALETTE gốc (primitive): thang màu thô 0–950, KHÔNG dùng trực tiếp.
 *   TẦNG 2 — SEMANTIC (token vai trò, bám Light/Dark): Surface · Text · Border ·
 *            Brand · Status · Categorical · Data-viz · Utility.
 * Status + Categorical hiển thị NGUYÊN BỘ VAI TRÒ (nền/viền/chữ/solid) cạnh nhau
 * — designer thấy ngay cách dùng, không phải đoán từ 1 ô -base. */

