/* ---------- TẦNG 2 · Bộ vai-trò (Status + Categorical) ---------- */
export interface Swatch {
  var: string;
  /** nhãn vai trò: Solid / Nền / Viền / Chữ / On */
  role: string;
  /** true → tính badge contrast (chữ) so với contrastOn */
  contrast?: boolean;
}
export interface ColorRow {
  name: string;
  swatches: Swatch[];
}

